{"code": "import os
from hermes_tools import read_file, search_files

def get_control_status(book):
    path = f"/home/bob/books/{book}/PROJECT_CONTROL_SHEET.md"
    if not os.path.exists(path):
        return "No control sheet"
    try:
        content = read_file(path)['content']
        # Look for lines with status, todo, pending
        lines = content.split('\n')
        relevant = [l.strip() for l in lines if any(k in l.lower() for k in ['status', 'todo', 'pending', 'next'])]
        if relevant:
            return '; '.join(relevant[:3])
        else:
            return "See control sheet"
    except Exception as e:
        return f"Error: {e}"

books = ["First_Generation", "Second_Generation", "Third_Generation", "MIFECO_AI_Playbook", "The_Unwritten_Future"]
for b in books:
    print(f"{b}: {get_control_status(b)}")"}
